function operationalItems(state,today){const end=new Date(today+'T12:00:00');end.setDate(end.getDate()+7);const limit=`${end.getFullYear()}-${String(end.getMonth()+1).padStart(2,'0')}-${String(end.getDate()).padStart(2,'0')}`;const due=[];for(const a of state.actions||[])if(!a.archived&&!a.done&&a.deadline&&a.deadline<=limit)due.push({type:'actions',id:a.id,name:a.name,date:a.deadline,kind:a.deadline<today?'Scaduta':'Azione'});for(const b of state.bills||[])if(!b.archived)for(const [field,kind] of [['due','Pagamento'],['renewal','Rinnovo'],['notice','Disdetta']])if(b[field]&&b[field]<=limit)due.push({type:'bills',id:b.id,name:b.name,date:b[field],kind});return {due:due.sort((a,b)=>a.date.localeCompare(b.date)),todayActions:(state.actions||[]).filter(a=>!a.archived&&!a.done&&a.scheduledDate===today),stalled:(state.projects||[]).filter(p=>!p.archived&&p.status==='Active'&&!p.nextAction?.trim())};}
function eventDay(event){if(event.start?.date)return event.start.date;const d=new Date(event.start?.dateTime);return Number.isNaN(d.valueOf())?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function safeGoogleLink(value){try{const u=new URL(value);return u.protocol==='https:'&&['calendar.google.com','meet.google.com','www.google.com'].includes(u.hostname)?u.href:'';}catch{return '';}}

