const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const format=value=>value===null||value===undefined||value===''?'—':Number(value).toLocaleString('it-IT',{maximumFractionDigits:2});
function visionHtml(text){return text.split('\n').map(line=>{const value=esc(line).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\[\[([^\]]+)\]\]/g,'$1');if(/^#{1,6} /.test(line))return '<h3>'+value.replace(/^#{1,6} /,'')+'</h3>';if(line==='---')return '<hr>';if(line.startsWith('- '))return '<p>• '+value.slice(2)+'</p>';if(line.startsWith('> '))return '<blockquote>'+value.slice(2)+'</blockquote>';return line?'<p>'+value+'</p>':'';}).join('');}
const dateLabel=date=>new Date(date+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'long',year:'numeric'});
const sandbox=new URLSearchParams(location.search).has('sandbox');
let store;try{store=openStore(sandbox?sessionStorage:localStorage);}catch{store=openStore({getItem(){throw Error('blocked');}});}let state=store.state;state.bills ||= [];
let dailyDate=localDate(),weeklyDate=weekStart(localDate(),state.settings.weekStart),monthlyDate=localDate().slice(0,7),financeMonth=monthlyDate,section='home',editorContext=null,filter='all',search='';
const pages=[['home','Home','home'],['north','North Star','compass'],['areas','Areas','grid'],['goals','Goals','target'],['projects','Projects','folder'],['actions','Next Actions','check'],['daily','Daily','sun'],['weekly','Weekly Review','week'],['monthly','Monthly Review','month'],['journal','Journal','pen'],['freedom','Freedom / Finanze','chart'],['bills','Utenze & ricorrenze','chart'],['history','Storico','clock'],['google','Calendar & Gmail','week'],['settings','Dati e decisioni','settings']];
const paths={home:'M3 10 12 3l9 7v10h-6v-6H9v6H3Z',compass:'m16 8-3 5-5 3 3-5Z M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',grid:'M3 3h7v7H3Z M14 3h7v7h-7Z M3 14h7v7H3Z M14 14h7v7h-7Z',target:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 11v2',folder:'M3 6h7l2 3h9v12H3Z',check:'m4 12 5 5L20 5',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l2 2 M17 17l2 2 M19 5l-2 2 M7 17l-2 2',week:'M4 5h16v16H4Z M4 10h16 M8 3v4 M16 3v4 M8 14h3 M14 14h3',month:'M4 5h16v16H4Z M4 10h16 M8 3v4 M16 3v4 M8 14h3 M14 14h3 M8 18h3',pen:'m4 20 1-5L17 3l4 4L9 19Z M14 6l4 4',chart:'M4 3v18h17 M8 16l4-5 4 2 4-7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l4 2',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;
function button(label,action,attrs='',className=''){return `<button type="button" class="${className}" data-action="${action}" ${attrs}>${label}</button>`;}
function link(label,page,attrs=''){return button(esc(label)+' <span aria-hidden="true">↗</span>','navigate',`data-page="${page}" ${attrs}`,'text-button');}
function heading(title,description,controls=''){return `<div class="heading"><div><h1>${title}</h1><p>${description}</p></div><div class="toolbar">${controls}</div></div>`;}
function card(title,body,extra=''){return `<section class="card ${extra}"><h2>${title}</h2>${body}</section>`;}
function hint(text){return `<p class="hint">${text}</p>`;}
function empty(text,action=''){return `<div class="empty">${text}${action}</div>`;}
function showNotice(text){$('notice').textContent=text;$('notice').hidden=!text;}
function save(){const result=store.save();$('save-status').textContent=(sandbox?'Sessione di prova · ':'')+result.message;if(!result.ok)showNotice(result.message);return result.ok;}
function getPath(path){return path.split('/').reduce((value,key)=>value?.[key],state);}
function setPath(path,value){const parts=path.split('/');let object=state;for(const key of parts.slice(0,-1)){if(object[key]===undefined)object[key]={};object=object[key];}object[parts.at(-1)]=value;}
function input(f,value='',binding='',name=f.id){const attrs=binding?`data-bind="${esc(binding)}"`:'';const id=`field-${name.replace(/[^a-zA-Z0-9_-]/g,'-')}`;
 if(f.type==='checkbox')return `<label class="check"><input id="${id}" name="${esc(name)}" type="checkbox" ${value===true?'checked':''} ${value===null||value===undefined||value===''?'data-unset="true"':''} ${attrs}><span>${esc(f.label)}</span></label>`;
 let control;if(f.type==='textarea')control=`<textarea id="${id}" name="${esc(name)}" rows="${f.rows||3}" ${attrs}>${esc(value)}</textarea>`;
 else if(f.type==='select')control=`<select id="${id}" name="${esc(name)}" ${attrs}>${f.options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value??'')===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`;
 else control=`<input id="${id}" name="${esc(name)}" type="${f.type||'text'}" value="${esc(value)}" ${f.type==='number'?`step="${f.step||'any'}" ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined?`max="${f.max}"`:''}`:''} ${f.required?'required':''} ${attrs}>`;
 return `<label class="field ${f.type==='textarea'?'wide':''}" for="${id}"><span>${esc(f.label)}</span>${control}<small class="field-error" aria-live="polite"></small></label>`;}
function bindFields(fields,prefix,obj={}){return `<div class="form-grid">${fields.map(f=>input(f,obj[f.id],`${prefix}/${f.id}`,prefix+'-'+f.id)).join('')}</div>`;}
function startDay(date){return state.daily[date]||emptyDaily();}
function money(month){return state.monthly[month]?.money||{};}
function review(type,key){return state[type][key]||{};}
function setTitle(){const page=pages.find(p=>p[0]===section);$('page-name').textContent=page?.[1]||'Home';document.title=`Life OS · ${page?.[1]||'Home'}`;document.querySelectorAll('#navigation a').forEach(a=>{a.classList.toggle('active',a.dataset.page===section);if(a.dataset.page===section)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
$('navigation').innerHTML=pages.map(([id,label,glyph],i)=>`${i===5?'<div class="nav-divider">VIVI & RIFLETTI</div>':i===10?'<div class="nav-divider">LIBERTÀ & MEMORIA</div>':''}<a class="nav" href="#${id}" data-page="${id}">${icon(glyph)}<span>${label}</span></a>`).join('');
function mount(html){$('content').innerHTML=html;document.querySelectorAll('[data-unset]').forEach(el=>el.indeterminate=true);updateComputed();if(section==='google'||section==='home')googleConnection.load().catch(e=>showNotice(e.message));}
function rhythm(w){const data=aggregate(state.daily,w,shiftDate(w,6));return ['pt','morningWorkout','deepWork','sleep'].map(id=>{const m=data.metrics.find(v=>v.id===id);return `<div class="stat"><span>${m.label}</span><strong>${format(m.value)} <small>${m.unit}</small></strong><small>${m.coverage} osservazioni</small></div>`;}).join('');}
function home(){const today=localDate(),d=startDay(today),w=weekStart(today,state.settings.weekStart),plan=state.plans[w]||['','',''],m=money(today.slice(0,7)),ratio=freedomRatio(m),activeGoals=state.goals.filter(g=>!g.archived&&g.priority==='NOW'&&g.status!=='Completed'),activeProjects=state.projects.filter(p=>!p.archived&&p.status==='Active');
 return heading('La tua giornata, in chiaro.',dateLabel(today)+' · scegli il prossimo passo.',`${button('+ Goal','new', 'data-type="goals"')}${button('+ Project','new','data-type="projects"')}${button('Daily Check-in','today','','primary')}`)+operationalHome()+`<details class="home-background"><summary>Direzione, progetti e riepiloghi</summary><section class="vision-banner"><div><span class="eyebrow">NORTH STAR · ORIZZONTE 3–5 ANNI</span><h2>${esc(state.northStar.statement)}</h2><p>Il lavoro è uno strumento della tua vita. Le esperienze ne fanno già parte.</p></div>${link('My Life Vision','north')}</section><div class="home-kpis">${kpi('GOALS NOW',activeGoals.length,'Massimo 2–3 priorità reali')}${kpi('PROJECTS ATTIVI',activeProjects.length,'Risultato → prossima azione')}${kpi('FREEDOM RATIO',ratio===null?'—':format(ratio)+'%','Obiettivo configurabile nelle finanze')}${kpi('FREEDOM SCORE',review('monthly',today.slice(0,7)).freedomScore?format(review('monthly',today.slice(0,7)).freedomScore)+'/10':'—','Valutazione personale del mese')}</div><div class="home-grid">${card('Da fare & da vivere',reminderHome())}${card('Utenze · prossime scadenze',billHome())}${card('Goals NOW',hint('I risultati che meritano la tua attenzione adesso.')+activeGoals.map(g=>compactEntity(g,'goals')).join('')+link('Tutti gli obiettivi','goals'))}${card('Questa settimana',hint(`${dateLabel(w)} → ${dateLabel(shiftDate(w,6))} · priorità della settimana corrente`)+`<ol class="priorities">${plan.map((text,i)=>`<li>${input(field('priority'+i,`Priorità ${i+1}`),text,`plans/${w}/${i}`,'home-priority'+i)}</li>`).join('')}</ol>`+link('Weekly Review','weekly'))}${card('Projects attivi',activeProjects.map(p=>compactEntity(p,'projects')).join('')+link('Tutti i progetti','projects'))}${card('Today',hint(dateLabel(today))+`<div class="today-grid">${kpi('SONNO',format(d.values.sleep)+' h','')}${kpi('ENERGY',format(d.values.energy)+' /5','')}${kpi('STRESS',format(d.values.stress)+' /5','')}${kpi('DEEP WORK',format(d.values.deepWork)+' min','')}</div><div class="today-focus"><span class="eyebrow">ONE BIG THING</span><p>${esc(d.bigThing)||'Scegli la cosa più importante di oggi.'}</p></div>`+button('Apri il Daily','today','','primary'))}${card('Next Actions',actionRows(false,5)+link('Tutte le prossime azioni','actions'))}${card('Money · questo mese',`<div class="today-grid">${kpi('INCOME',m.income===undefined||m.income===''?'—':'€ '+format(m.income),'')}${kpi('SPESA PERSONALE',m.personalSpending===undefined||m.personalSpending===''?'—':'€ '+format(m.personalSpending),'Confermata nella Monthly')}${kpi('CASH',m.cash===undefined||m.cash===''?'—':'€ '+format(m.cash),'')}${kpi('NET WORTH',m.netWorth===undefined||m.netWorth===''?'—':'€ '+format(m.netWorth),'')}</div>`+link('Freedom / Finanze','freedom'))}${card('Agenda personale',googleAgenda()+link('Calendar & Gmail','google'))}${card('Il ritmo della settimana',`<div class="stats-grid small-stats">${rhythm(w)}</div>`+hint('PT è un target settimanale. Nessun campo mancante è trasformato in una sessione non fatta.')+link('Numeri e riflessioni','weekly'))}${card('Il ritmo delle review',`<p>Il tracker raccoglie. Il journal spiega. La Weekly interpreta. La Monthly corregge.</p><div class="review-links">${link('Weekly · 15–20 min','weekly')}${link('Monthly · 30–45 min','monthly')}${link('Journal · scrittura libera','journal')}</div><p class="hint">Quarterly: livello concordato, template ancora da definire.</p>`)} </div></details>`;
}
function kpi(label,value,desc){return `<div class="kpi"><span class="eyebrow">${label}</span><strong>${esc(value)}</strong>${desc?`<small>${desc}</small>`:''}</div>`;}
function compactEntity(e,type){return `<button class="compact-entity" data-action="edit" data-type="${type}" data-id="${esc(e.id)}"><div><strong>${esc(e.name)}</strong><small>${esc(e.nextAction)||'Next Action da definire'}</small></div><span>${e.progress===''?'—':format(e.progress)+'%'}</span></button>`;}
function north(){return heading('La vita che vuoi costruire.','My Life Vision · una direzione a 3–5 anni, da rivedere con calma.',button('Modifica la visione','edit-north','','primary'))+`<section class="vision-banner"><span class="eyebrow">LA TUA NORTH STAR</span><h2>${esc(state.northStar.statement)}</h2></section><div class="home-grid">${card('My Life Vision',`<div class="readable">${visionHtml(state.northStar.vision||'Caricamento della visione dalla specifica…')}</div>`)}${card('Decision Filter',`<p>Questa scelta aumenta o diminuisce la mia libertà?</p><ul class="principles"><li>Financial Freedom · possibilità di scelta</li><li>Time Freedom · controllo del tempo</li><li>Geographic Freedom · vivere e lavorare tra luoghi diversi</li><li>Mental Freedom · meno pressione</li><li>Relationships · qualità dei legami</li><li>Experiences · vita vissuta</li></ul>${bindFields([field('decisionNotes','Riflessioni sulle decisioni','textarea')],'northStar',state.northStar)}${revisionList(state.northStar)}`)}</div>`;}
function areas(){return heading('Le aree non finiscono.','Otto dimensioni permanenti. Compilale quando hanno qualcosa da dirti.')+`<div class="area-grid">${state.areas.map(a=>card(esc(a.name),`<div class="area-score">${a.score===''?'—':format(a.score)}<span>/10 · manuale</span></div><p>${esc(a.desired)||'Come vuoi che sia quest’area della tua vita?'}</p><div class="area-links">${link(state.goals.filter(g=>!g.archived&&g.areaId===a.id).length+' Goals','goals',`data-area="${a.id}"`)}${link(state.projects.filter(p=>!p.archived&&p.areaId===a.id).length+' Projects','projects',`data-area="${a.id}"`)}</div>${button('Apri / modifica','edit','data-type="areas" data-id="'+a.id+'"')}`)).join('')}</div>`;}
function entityCard(e,type){const area=state.areas.find(a=>a.id===e.areaId),goal=state.goals.find(g=>g.id===e.goalId),related=type==='goals'?state.projects.filter(p=>p.goalId===e.id&&!p.archived):state.actions.filter(a=>a.projectId===e.id&&!a.archived);
 return `<article class="card entity-card"><div class="entity-top"><span class="pill ${e.priority==='NOW'||e.status==='Active'?'green':''}">${esc(e.priority)} · ${esc(e.status)}</span><span class="hint">${esc(area?.name||'Area da collegare')}</span></div><h2>${esc(e.name)}</h2>${e.source?hint(esc(e.source)):''}<p>${esc(e.outcome)||'Outcome da definire'}</p><div class="entity-progress"><span>Progresso manuale</span><strong>${e.progress===''?'Da valutare':format(e.progress)+'%'}</strong></div><progress max="100" value="${Number(e.progress)||0}" aria-label="Progresso di ${esc(e.name)}"></progress><p class="deadline">Scadenza: ${e.deadline?dateLabel(e.deadline):'Non definita'}</p><div class="next-action"><span class="eyebrow">NEXT ACTION</span><p>${esc(e.nextAction)||'Manca la prossima azione concreta.'}</p>${e.nextAction?input(field('nextDone','Completata','checkbox'),e.nextDone,`${type}/${state[type].indexOf(e)}/nextDone`,e.id+'-done'):''}</div>${goal?link('Goal → '+goal.name,'goals'):''}<details><summary>Dettagli, relazioni e memoria</summary><dl>${[['Perché',e.why],['Condizione di successo',e.successCondition],['Situazione attuale',e.currentSituation],['Blockers',e.blockers],['Notes',e.notes]].map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)||'—'}</dd>`).join('')}</dl><h3>Milestones</h3>${milestones(e,type)}<h3>${type==='goals'?'Projects collegati':'Tasks collegati'}</h3>${related.map(r=>type==='goals'?compactEntity(r,'projects'):`<p>${r.done?'✓':'○'} ${esc(r.name)}</p>`).join('')||hint('Nessun elemento collegato.')}<h3>Last Review</h3><pre class="review-text">${esc(lastReviewText(e.lastReview))}</pre>${revisionList(e)}</details><div class="entity-buttons">${button('Modifica','edit',`data-type="${type}" data-id="${esc(e.id)}"`)}${type==='projects'?button('+ Task','new-action',`data-project="${esc(e.id)}"`):button('+ Project','new-project',`data-goal="${esc(e.id)}"`)}${button(e.archived?'Ripristina':'Archivia','archive',`data-type="${type}" data-id="${esc(e.id)}"`,'text-button')}</div></article>`;}
function milestones(e,type){return e.milestones.map((m,i)=>`<label class="check"><input type="checkbox" data-bind="${type}/${state[type].indexOf(e)}/milestones/${i}/done" ${m.done?'checked':''}><span>${esc(m.text)}</span></label>`).join('')||hint('Aggiungi le milestone da Modifica. Il progresso resta manuale.');}
function lastReviewText(r={}){return Object.entries(r).filter(([,v])=>v!==''&&v!==undefined).map(([k,v])=>`${k}: ${v}`).join('\n')||'Nessuna review registrata.';}
function revisionList(e){return `<details class="revisions"><summary>Versioni salvate (${e.history?.length||0})</summary>${(e.history||[]).slice().reverse().map(r=>`<details><summary>${new Date(r.at).toLocaleString('it-IT')}</summary><pre class="review-text">${esc(JSON.stringify(r.data,null,2))}</pre></details>`).join('')||hint('Le modifiche salvate dall’editor conservano la versione precedente.')}</details>`;}
function entities(type){const isGoal=type==='goals',all=state[type].filter(e=>filter==='archived'?e.archived:!e.archived).filter(e=>!search||e.name.toLowerCase().includes(search.toLowerCase())).filter(e=>['all','archived'].includes(filter)||filter.startsWith('area:')&&e.areaId===filter.slice(5)||filter==='blocked'&&(isGoal?e.status==='Blocked':Boolean(e.blockers?.trim())||!e.nextAction.trim())||filter==='someday'&&e.status==='Idea'||filter==='deadline'&&e.deadline&&e.status!=='Completed'||e.status===filter||e.priority===filter);
 const opts=isGoal?[['all','Tutti'],['NOW','NOW'],['NEXT','NEXT'],['LATER','LATER'],['someday','Someday / Maybe · Idea'],['blocked','Blocked'],['Completed','Completed'],['deadline','Scadenziario'],['archived','Archivio']]:[['all','Tutti'],['Active','Active'],['Planned','Upcoming · Planned'],['On Hold','On Hold'],['Idea','Ideas'],['Completed','Completed'],['blocked','Attenzione / Next Action mancante'],['deadline','Scadenziario'],['archived','Archivio']];
 return heading(isGoal?'Risultati, non liste infinite.':'Dalla direzione alle cose concrete.',isGoal?'NOW / NEXT / LATER indicano attenzione e sequenza, non durate rigide.':'Un progetto ha un risultato concreto, una fine e una Next Action.',button(isGoal?'+ Nuovo Goal':'+ Nuovo Project','new',`data-type="${type}"`,'primary'))+`<div class="filter-bar"><label>Cerca <input id="entity-search" type="search" value="${esc(search)}" placeholder="Nome ${isGoal?'obiettivo':'progetto'}"></label><label>Vista <select id="entity-filter">${opts.concat(state.areas.map(a=>['area:'+a.id,a.name])).map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select></label></div>`+(isGoal&&state.goals.filter(g=>!g.archived&&g.priority==='NOW'&&g.status!=='Completed').length>3?'<p class="notice">Hai più di 3 Goals NOW: scegli poche priorità realmente importanti.</p>':'')+`<div class="entity-grid">${all.sort((a,b)=>filter==='deadline'?a.deadline.localeCompare(b.deadline):0).map(e=>entityCard(e,type)).join('')||empty('Nessun elemento in questa vista.')}</div>`;}
function allActions(){return [...state.goals.filter(g=>!g.archived&&g.status!=='Completed'&&g.nextAction).map(g=>({id:g.id,name:g.nextAction,done:g.nextDone,parent:g,type:'goals',label:'Goal · '+g.name})),...state.projects.filter(p=>!p.archived&&p.status!=='Completed'&&p.nextAction).map(p=>({id:p.id,name:p.nextAction,done:p.nextDone,parent:p,type:'projects',label:'Project · '+p.name})),...state.actions.filter(a=>!a.archived).map(a=>({...a,parent:a,type:'actions',label:'Task · '+(state.projects.find(p=>p.id===a.projectId)?.name||'Senza progetto')}))];}
function actionRows(completed=false,limit=Infinity){const list=allActions().filter(a=>Boolean(a.done)===completed).slice(0,limit);return list.map(a=>`<div class="action-row"><label class="check"><input type="checkbox" data-bind="${a.type}/${state[a.type].indexOf(a.parent)}/${a.type==='actions'?'done':'nextDone'}" ${a.done?'checked':''}><span><strong>${esc(a.name)}</strong><small>${esc(a.label)}${a.deadline?' · '+dateLabel(a.deadline):''}</small></span></label><div>${button('Oggi','use-today',`data-type="${a.type}" data-id="${esc(a.id)}"`,'text-button')}${button('Apri','edit',`data-type="${a.type}" data-id="${esc(a.id)}"`,'text-button')}</div></div>`).join('')||empty(completed?'Nessuna azione completata.':'Nessuna Next Action aperta. Aggiungila a un Goal o Project.');}
function actions(){return heading('Il prossimo passo concreto.','Le Next Actions fanno avanzare i progetti. Le abitudini restano nel Daily.',button('+ Nuova azione','new-action','','primary'))+card('Da fare',actionRows())+card('Completate',actionRows(true));}
function periodNav(type,value,inputType){return `<div class="date-nav">${button('←','period-prev',`data-type="${type}" aria-label="Periodo precedente"`)}<label class="sr-only" for="period">Periodo</label><input id="period" type="${inputType}" value="${value}" data-period="${type}">${button('→','period-next',`data-type="${type}" aria-label="Periodo successivo"`)}${button(type==='daily'?'Oggi':'Periodo attuale','period-today',`data-type="${type}"`)}</div>`;}
function daily(){const d=startDay(dailyDate),prefix='daily/'+dailyDate;const monday=weekStart(dailyDate,state.settings.weekStart);return heading('Una giornata alla volta.','Daily Check-in · 2–3 minuti. Campi vuoti significano non osservati.',periodNav('daily',dailyDate,'date'))+`<div class="day-top"><div><span class="eyebrow">${new Date(dailyDate+'T12:00:00').toLocaleDateString('it-IT',{weekday:'long'})}</span><h2>${dateLabel(dailyDate)}</h2><div class="week-strip">${Array.from({length:7},(_,i)=>{const date=shiftDate(monday,i);return button(`<span>${new Date(date+'T12:00:00').toLocaleDateString('it-IT',{weekday:'short'})}</span><strong>${Number(date.slice(-2))}</strong>`,'day',`data-date="${date}" aria-label="${dateLabel(date)}" aria-pressed="${date===dailyDate}"`,date===dailyDate?'selected':'');}).join('')}</div></div><div class="daily-score"><span class="eyebrow">DAILY SCORE · SPERIMENTALE</span><strong id="daily-score-value"></strong><p id="daily-score-caption"></p>${link('Formula e decisioni','settings')}</div></div>${d.migrated?hint('Giornata migrata dalla v1. Solo i campi con equivalenza certa sono stati trasferiti; tutti gli originali sono nell’Archivio v1.'):''}<section class="card focus-card"><div><span class="eyebrow">LA TUA PRIORITÀ</span><h2>One Big Thing</h2></div><div class="focus-content">${bindFields([field('bigThing','La cosa più importante oggi'),field('bigDone','Completed','checkbox'),field('projectId','Project collegato','select',{options:[['','Nessun progetto'],...state.projects.filter(p=>!p.archived).map(p=>[p.id,p.name])]})],prefix,d)}${d.actionId?hint('Collegata a una Next Action. La completion resta esplicita nella sezione Next Actions.'):''}</div></section><div class="daily-grid">${DAILY_GROUPS.map(([title,subtitle,fields])=>card(title,hint(subtitle)+fields.map(f=>{const sub=f.type==='checkbox'?'habits':f.id==='closer'||f.type==='textarea'?'':'values';return input(f,sub?d[sub][f.id]:d[f.id],`${prefix}/${sub?sub+'/':''}${f.id}`,f.id);}).join(''))).join('')}</div>${card('Journal',hint('Il diario quotidiano vive qui. Nessun conteggio di parole o tempo.')+bindFields([field('journal','Cosa è successo oggi?','textarea',{rows:5}),field('thoughts','Cosa ho in mente?','textarea',{rows:4})],prefix,d)+(state.settings.scoreMode==='proposal9'&&state.settings.journalCriterion==='flag'?bindFields([field('journalDone','Diario scritto · flag sperimentale','checkbox')],prefix,d):''))}${state.legacyDays[dailyDate]?card('Score e dati originali v1',`<p>Score originale: <strong>${legacyScore(state.legacyDays[dailyDate])}/100</strong> · proposta implementata, non approvata. Non comparabile con la proposta a nove condizioni.</p>${link('Apri archivio v1 completo','legacy')}`):''}`;}
function stats(start,end){const data=aggregate(state.daily,start,end);return `<div class="stats-head"><h2>The Numbers</h2><span class="pill">${data.coverage} giornate registrate</span></div><p class="hint">${dateLabel(start)} → ${dateLabel(end)}. Medie sui valori compilati; mancanti esclusi. Totali parziali. La copertura è indicata per ogni metrica.</p><div class="stats-grid">${data.metrics.map(m=>`<div class="stat"><span>${m.label}</span><strong>${format(m.value)} <small>${m.unit}</small></strong><small>${m.coverage} osservazioni</small></div>`).join('')}</div>`;}
function reviewGroups(groups,type,key,r){return groups.map(([title,fields])=>card(title,bindFields(fields,`${type}/${key}`,r))).join('');}
function planCard(date,title){const plan=state.plans[date]||['','',''];return card(title,hint(`Settimana ${dateLabel(date)} · la Home legge questi stessi dati.`)+`<div class="form-grid">${plan.map((text,i)=>input(field('priority'+i,`Priorità ${i+1}`),text,`plans/${date}/${i}`,'plan-'+i)).join('')}</div>`);}
function weekly(){const r=review('weekly',weeklyDate),end=shiftDate(weeklyDate,6),next=shiftDate(weeklyDate,7);return heading('Fermati. Osserva. Scegli.','Weekly Review · 15–20 minuti. Numeri, pattern e poche decisioni.',periodNav('weekly',weeklyDate,'date'))+card('La settimana',stats(weeklyDate,end))+planCard(weeklyDate,'Le priorità di questa settimana')+`<div class="review-grid">${reviewGroups(WEEKLY_GROUPS,'weekly',weeklyDate,r)}</div>`+planCard(next,'Le 3 priorità per la prossima settimana')+card('Le 3 decisioni per la prossima settimana',bindFields(Array.from({length:3},(_,i)=>field('decision'+i,`Decisione ${i+1}`)),`weekly/${weeklyDate}`,r))+card('Goals & Projects attuali',hint('Consulta e aggiorna gli elementi. La review descrive ciò che è successo nel periodo, senza attribuire retroattivamente lo stato attuale.')+link('Goals','goals')+link('Projects','projects'))+card('Memoria della review',button('Salva versione della review','snapshot-review','data-type="weekly"')+revisionList(r));}
function scorecard(r){return `<div class="table-wrap"><table><thead><tr><th>Dimensione</th><th>Score /10</th><th>Trend</th></tr></thead><tbody>${SCORECARD.map((name,i)=>`<tr><td>${name}</td><td>${input(field('score'+i,'Score '+name,'number',{min:1,max:10}),r.scorecard?.[i]?.score,`monthly/${monthlyDate}/scorecard/${i}/score`,'score-'+i)}</td><td>${input(field('trend'+i,'Trend '+name,'select',{options:[['','Non valutato'],['↑','↑ Migliora'],['→','→ Stabile'],['↓','↓ Peggiora']]}),r.scorecard?.[i]?.trend,`monthly/${monthlyDate}/scorecard/${i}/trend`,'trend-'+i)}</td></tr>`).join('')}</tbody></table></div>`;}
function monthly(){const r=review('monthly',monthlyDate);return heading('Correggi la rotta.','Monthly Review · 30–45 minuti. La vita che stai costruendo, oltre i numeri.',periodNav('monthly',monthlyDate,'month'))+card('Life Scorecard',hint('15 dimensioni trasversali, distinte dalle 8 Areas permanenti. Voti e trend sono giudizi manuali supportati dai dati.')+scorecard(r)+bindFields([field('freedomScore','Overall Freedom · /10','number',{min:1,max:10}),field('freedomWhy','Quanto mi sento libero? Perché?','textarea')],`monthly/${monthlyDate}`,r))+card('Month in Numbers',stats(monthlyDate+'-01',monthEnd(monthlyDate)))+card('Money',moneyForm(monthlyDate))+`<div class="review-grid">${reviewGroups(MONTHLY_GROUPS,'monthly',monthlyDate,r)}</div>`+card('Memoria del mese',button('Salva versione della review','snapshot-review','data-type="monthly"')+revisionList(r));}
function moneyForm(month){const m=money(month),sum=aggregate(state.daily,month+'-01',monthEnd(month)).metrics.find(v=>v.id==='spending');return `<p class="hint">I saldi storici non sono valori attuali. Income e reddito ricorrente sono distinti. La spesa mensile confermata può includere giorni non compilati; non viene sommata di nuovo al Daily.</p><div class="money-summary" data-money-month="${month}"></div>${hint(`Spese personali dai Daily: € ${format(sum.value)} · ${sum.coverage} osservazioni, totale parziale.`)}${bindFields(MONEY_FIELDS,`monthly/${month}/money`,m)}`;}
function freedom(){const m=money(financeMonth);return heading('Il denaro compra possibilità.','Financial, Time, Geographic e Mental Freedom. Libertà vissuta e copertura economica sono distinte.',periodNav('freedom',financeMonth,'month'))+`<section class="vision-banner"><div><h2>La tua libertà economica</h2><p>Imposta un obiettivo di entrate mensili per calcolare il Freedom Ratio.</p></div></section>`+card('Finanze del mese',moneyForm(financeMonth))+card('Le quattro libertà',`<div class="freedom-dimensions"><p><strong>Financial</strong><br>Possibilità di scelta economica.</p><p><strong>Time</strong><br>Controllo del tempo.</p><p><strong>Geographic</strong><br>Libertà di scegliere dove stare.</p><p><strong>Mental</strong><br>Meno pressione e rumore.</p></div>${link('Valuta il Freedom Score nella Monthly','monthly')}`)+``;}
function journal(){const entries=state.journals.filter(j=>filter==='archived'?j.archived:!j.archived).sort((a,b)=>b.date.localeCompare(a.date));return heading('Uno spazio per capire.','Riflessioni indipendenti dal Daily. I prompt sono facoltativi.',`${button('+ Scrivi una nota','new','data-type="journals"','primary')}${button(filter==='archived'?'Note attive':'Archivio','journal-filter')}`)+`<div class="journal-list">${entries.map(j=>card(esc(j.name||'Riflessione senza titolo'),hint(dateLabel(j.date))+`<p class="journal-preview">${esc(j.mind||'')}</p>${j.insight?`<p><strong>Insight:</strong> ${esc(j.insight)}</p>`:''}${j.actionNeeded==='yes'?`<p>Prossima azione: ${esc(j.action||'Da definire')}</p>${button('Crea una Next Action','journal-action',`data-id="${esc(j.id)}"`)}`:''}${button('Apri / modifica','edit',`data-type="journals" data-id="${esc(j.id)}"`)}${button(j.archived?'Ripristina':'Archivia','archive',`data-type="journals" data-id="${esc(j.id)}"`,'text-button')}${revisionList(j)}`)).join('')||empty('Non serve una struttura perfetta. Inizia da un pensiero.')}</div>`;}
function history(){const items=[...Object.entries(state.daily).map(([date,d])=>({date,type:'daily',title:d.bigThing||'Daily Check-in',detail:d.migrated?'Migrato v1':'Daily finale'})),...Object.entries(state.weekly).map(([date,r])=>({date,type:'weekly',title:r.sentence||'Weekly Review',detail:'Review della settimana'})),...Object.entries(state.monthly).map(([date,r])=>({date:date+'-01',key:date,type:'monthly',title:r.sentence||'Monthly Review',detail:'Review del mese'})),...state.journals.map(j=>({date:j.date,type:'journal',id:j.id,title:j.name,detail:j.archived?'Journal archiviato':'Journal'}))].sort((a,b)=>b.date.localeCompare(a.date));return heading('La memoria del tuo percorso.','Daily, review e journal per data. Nessuna media fra score diversi.',`${button('Esporta backup','export')}${link('Daily v1 completo','legacy')}`)+card(`${items.length} elementi nello storico`,items.map(item=>`<button class="timeline-row" data-action="open-history" data-type="${item.type}" data-date="${item.key||item.date}" ${item.id?`data-id="${esc(item.id)}"`:''}><span>${dateLabel(item.date)}<small>${item.detail}</small></span><strong>${esc(item.title)}</strong><span aria-hidden="true">→</span></button>`).join('')||empty('Le giornate e le review compariranno qui quando inizierai a compilarle.'));}
function legacy(){return heading('Il primo tracker, conservato.','Tutti i campi, lo score originale e lo storico v1 restano disponibili. Le modifiche qui appartengono all’archivio v1.')+hint('La migrazione iniziale trasferisce solo i campi equivalenti. Puoi importare le nuove giornate v1 mancanti; quelle già presenti nel Daily finale non vengono sovrascritte.')+button('Recupera giornate v1 mancanti','refresh-legacy')+`<iframe src="legacy-index.html${sandbox?'?sandbox=1':''}" title="Daily Tracker originale v1" class="legacy-frame"></iframe>`;}
function settings(){return heading('I tuoi dati. Le tue decisioni.','Backup portabile e scelte sperimentali dichiarate. Nessun account richiesto.')+`<div class="home-grid">${card('Backup e trasferimento',`<p>Salvato su questo browser e indirizzo. Localhost, Vercel e altri dispositivi hanno archivi separati.</p><div class="toolbar">${button('Esporta tutto · JSON','export','','primary')}${button('Importa backup · anteprima','import')}${button('Scarica copia prima dell’ultimo import','export-recovery')}</div><p class="hint">L’importazione unisce gli elementi. Puoi scegliere come gestire gli identificatori già esistenti. L’archivio v1 è incluso nel backup.</p>`)}${card('Calendario operativo',bindFields([field('weekStart','Inizio settimana · scelta modificabile','select',{options:[[1,'Lunedì'],[0,'Domenica']]})],'settings',state.settings)+hint('Le review già salvate mantengono le loro date iniziali. La scelta influenza solo la navigazione e i nuovi periodi. Le medie escludono valori mancanti; zero compilato è un’osservazione. Meditazione: giorni con minuti > 0.'))}${card('Daily Score · proposta da validare',`<p>La formula della prima web app è conservata nell’Archivio v1. La specifica propone un’altra formula a nove condizioni, ancora da validare. Non sono confrontabili.</p>${bindFields([field('scoreMode','Score nel Daily finale','select',{options:[['off','Nessuna formula definitiva · non calcolare'],['proposal9','Mostra proposta sperimentale a 9 condizioni']]}),field('journalCriterion','Criterio Journal · solo per la proposta','select',{options:[['text','Presenza di testo nel Journal Daily'],['flag','Flag esplicito Diario scritto']]})],'settings',state.settings)}<p class="hint">La proposta considera morning workout, walking, food, sleep, meditation, deep work, One Big Thing, diario e direzione. PT, stress, alcol e screen time non penalizzano. Cambiare i target ricalcola l’anteprima; non crea una formula definitiva.</p>${bindFields([field('walking','Walking · min','number',{min:1}),field('sleep','Sleep · h','number',{min:0.1,max:24}),field('foodQuality','Food quality · /5','number',{min:1,max:5}),field('meditation','Meditation · min','number',{min:1}),field('deepWork','Deep Work · min','number',{min:1})],'settings/targets',state.settings.targets)}`)}${card('Registro delle decisioni',`<dl><dt>Concordato</dt><dd>North Star → Areas → Goals → Projects → Next Actions → Daily → Weekly → Monthly. Progresso, Life Scorecard e Freedom Score manuali. Obiettivo finanziario configurabile.</dd><dt>Proposto</dt><dd>Daily Score, target sperimentali,  esperimenti di vita, progresso automatico e integrazione futura.</dd><dt>Da definire</dt><dd>Formula definitiva e journalDone; Quarterly; sync; molti-a-molti; saldi reali. Non bloccano questa versione autonoma.</dd></dl><p class="hint">Someday / Maybe è una vista delle Idea, non un quarto valore di priorità. La configurazione Obsidian è rinviata.</p>`)}</div>`;}
function updateComputed(){const score=$('daily-score-value');if(score){const d=startDay(dailyDate);score.textContent=state.settings.scoreMode==='proposal9'?proposalScore(d,state.settings)+'/100':'—';$('daily-score-caption').textContent=state.settings.scoreMode==='proposal9'?'Anteprima a nove condizioni · non formula definitiva.':'Formula definitiva da validare. Lo score originale resta nell’Archivio v1.';}
 document.querySelectorAll('[data-money-month]').forEach(el=>{const m=money(el.dataset.moneyMonth),ratio=freedomRatio(m);el.innerHTML=`${kpi('FREEDOM RATIO',ratio===null?'—':format(ratio)+'%','Reddito ricorrente / obiettivo mensile')}${kpi('CASH',m.cash===''||m.cash===undefined?'—':'€ '+format(m.cash),'Saldo inserito')}${kpi('NET WORTH',m.netWorth===''||m.netWorth===undefined?'—':'€ '+format(m.netWorth),'Saldo inserito')}${kpi('PROPERTY CASH FLOW',m.propertyIncome!==undefined&&m.propertyIncome!==''&&m.propertySpending!==undefined&&m.propertySpending!==''?'€ '+format(Number(m.propertyIncome)-Number(m.propertySpending)):'—','Income − Property spending')}`;});}
function render(resetScroll=false){setTitle();const views={home,north,areas,goals:()=>entities('goals'),projects:()=>entities('projects'),actions,daily,weekly,monthly,journal,freedom,history,settings,legacy,google:googleView,bills:billView};mount((views[section]||home)());if(resetScroll)window.scrollTo({top:0,behavior:'instant'});}
function navigate(page){if(page!==section){filter='all';search='';}if(location.hash==='#'+page){section=page;render();}else location.hash=page;}
function snapshot(e){const data=structuredClone(e);delete data.history;(e.history||=[]).push({at:new Date().toISOString(),data});}
const editCommon=[field('name','Nome','text',{required:true}),field('areaId','Area','select'),field('priority','Priority','select'),field('status','Status','select'),field('deadline','Deadline','date'),field('progress','Progress · % manuale','number',{min:0,max:100}),field('outcome','Outcome · risultato concreto','textarea'),field('successCondition','Come saprò di averlo raggiunto?','textarea'),field('why','Why · contributo alla North Star','textarea'),field('currentSituation','Current Situation','textarea'),field('nextAction','Next Action · singola azione concreta'),field('nextDone','Next Action completata','checkbox'),field('blockers','Blockers','textarea'),field('notes','Notes','textarea')];
function showEditor(type,id=null,defaults={}){let e=id?state[type].find(item=>item.id===id):null;let fields=[];if(type==='northStar'){e=state.northStar;fields=[field('statement','North Star','textarea'),field('vision','My Life Vision · testo completo','textarea',{rows:16})];}
 else if(type==='areas'){fields=[field('desired','Desired State','textarea'),field('current','Current State','textarea'),field('score','Score · /10','number',{min:1,max:10}),field('attention','Attention','textarea'),field('notes','Notes','textarea'),field('reviewDate','Last Review · data','date'),field('reviewScore','Last Review · score /10','number',{min:1,max:10}),field('reviewTrend','Last Review · trend','select',{options:[['','Non valutato'],'↑','→','↓']}),field('reviewGood','Cosa sta andando bene?','textarea'),field('reviewImprove','Cosa deve migliorare?','textarea'),field('reviewDecision','Prossima decisione','textarea')];}
 else if(type==='goals'||type==='projects'){if(!e)e={...makeEntity(type),...defaults};fields=editCommon.filter(f=>type==='goals'||f.id!=='successCondition').map(f=>({...f}));fields.find(f=>f.id==='areaId').options=[['','Da collegare'],...state.areas.map(a=>[a.id,a.name])];fields.find(f=>f.id==='priority').options=type==='goals'?['NOW','NEXT','LATER']:['High','Medium','Low'];fields.find(f=>f.id==='status').options=type==='goals'?GOAL_STATUS:PROJECT_STATUS;if(type==='projects')fields.splice(2,0,field('goalId','Goal collegato','select',{options:[['','Nessun Goal'],...state.goals.filter(g=>!g.archived).map(g=>[g.id,g.name])]}));fields.push(field('milestoneText','Milestones · una per riga','textarea'),field('reviewDate','Last Review · data','date'),field('reviewProgress','Last Review · progresso %','number',{min:0,max:100}),field('reviewChanged',type==='goals'?'Cosa è cambiato?':'Problemi','textarea'),field('reviewDecision',type==='goals'?'Prossima decisione':'Decisioni','textarea'));if(type==='projects')fields.push(field('reviewNext','Last Review · Next Action'));}
 else if(type==='bills'){if(!e)e={id:uid(),name:'',category:'Casa',provider:'',amount:'',interval:1,due:'',renewal:'',notice:'',method:'',notes:'',payments:[],history:[],archived:false};fields=[field('name','Utenza o contratto','text',{required:true}),field('category','Categoria','select',{options:['Casa','Internet & telefono','Assicurazione','Auto','Abbonamento','Altro']}),field('provider','Fornitore / compagnia'),field('amount','Importo previsto · €','number',{min:0}),field('interval','Frequenza','select',{options:[['','Variabile / una tantum'],[1,'Mensile'],[2,'Bimestrale'],[3,'Trimestrale'],[6,'Semestrale'],[12,'Annuale']]}),field('due','Prossima scadenza','date'),field('renewal','Rinnovo contratto','date'),field('notice','Disdetta entro','date'),field('method','Metodo di pagamento / addebito'),field('notes','Note · riferimento contratto','textarea')];}
 else if(type==='actions'){if(!e)e={id:uid(),name:'',projectId:'',deadline:'',done:false,notes:'',history:[],archived:false,...defaults};fields=[field('name','Azione concreta','text',{required:true}),field('projectId','Project','select',{options:[['','Senza progetto'],...state.projects.filter(p=>!p.archived).map(p=>[p.id,p.name])]}),field('deadline','Scadenza','date'),field('done','Completata','checkbox'),field('notes','Notes','textarea')];if(e.reminder)fields.push(field('target','Quante volte / quantità da completare','number',{min:1,step:1}),field('count','Già completate','number',{min:0,step:1}));}
 else if(type==='journals'){if(!e)e={id:uid(),name:'',date:localDate(),mind:'',thinking:'',insight:'',actionNeeded:'',action:'',history:[],archived:false};fields=[field('name','Titolo'),field('date','Date','date',{required:true}),field('mind','What’s on my mind? · scrittura libera','textarea',{rows:10}),field('thinking','What am I really thinking? · opzionale','textarea'),field('insight','Insight · opzionale','textarea'),field('actionNeeded','Questa riflessione richiede un’azione?','select',{options:[['','Non valutato'],['no','No'],['yes','Sì']]}),field('action','Action · eventuale prossima azione')];}
 const draft={...structuredClone(e),milestoneText:e.milestones?.map(m=>m.text).join('\n')||'',reviewDate:e.lastReview?.date||'',reviewScore:e.lastReview?.score??'',reviewTrend:e.lastReview?.trend||'',reviewGood:e.lastReview?.good||'',reviewImprove:e.lastReview?.improve||'',reviewDecision:e.lastReview?.decision||'',reviewProgress:e.lastReview?.progress??'',reviewChanged:e.lastReview?.changed||'',reviewNext:e.lastReview?.next||''};editorContext={type,id,entity:e,fields};$('editor-title').textContent=type==='northStar'?'My Life Vision':(id?e.name:type==='goals'?'Nuovo Goal':type==='projects'?'Nuovo Project':type==='actions'?(e.reminder?'Nuovo promemoria':'Nuova azione'):type==='bills'?'Nuova utenza':'Nuovo Journal');$('editor-kind').textContent=type==='goals'?'RISULTATO':type==='projects'?'INIZIATIVA FINITA':type.toUpperCase();$('editor-fields').innerHTML=`<div class="form-grid">${fields.map(f=>input(f,draft[f.id])).join('')}</div>`+(id?revisionList(e):'');$('form-error').textContent='';$('editor').showModal();}
$('editor-form').onsubmit=e=>{e.preventDefault();if(!$('editor-form').reportValidity())return;const {type,id,entity,fields}=editorContext;const draft=structuredClone(entity);fields.forEach(f=>{const el=$('editor-form').elements.namedItem(f.id);draft[f.id]=f.type==='checkbox'?el.checked:f.type==='number'&&el.value!==''?Number(el.value):el.value;});if(type==='bills')draft.interval=draft.interval===''?'':Number(draft.interval);if(type==='actions'&&draft.reminder){if(draft.count>draft.target){$('form-error').textContent='Le completate non possono superare il totale.';return;}draft.done=draft.done||draft.count===draft.target;if(draft.done)draft.count=draft.target;}if(type==='goals'&&draft.priority==='NOW'&&draft.status!=='Completed'&&state.goals.filter(g=>g.id!==draft.id&&!g.archived&&g.priority==='NOW'&&g.status!=='Completed').length>=3){$('form-error').textContent='NOW contiene già 3 obiettivi. Spostane uno a NEXT/LATER oppure scegli un’altra priorità.';return;}
 if(type==='goals'||type==='projects'){const used=new Set();draft.milestones=draft.milestoneText.split('\n').map(text=>text.trim()).filter(Boolean).map(text=>{const old=entity.milestones.find(m=>m.text===text&&!used.has(m.id));if(old)used.add(old.id);return old||{id:uid(),text,done:false};});delete draft.milestoneText;}
 if(type==='areas'||type==='goals'||type==='projects'){draft.lastReview={date:draft.reviewDate,score:draft.reviewScore,trend:draft.reviewTrend,good:draft.reviewGood,improve:draft.reviewImprove,decision:draft.reviewDecision,progress:draft.reviewProgress,changed:draft.reviewChanged,next:draft.reviewNext};Object.keys(draft).filter(k=>k.startsWith('review')).forEach(k=>delete draft[k]);}
 draft.updatedAt=new Date().toISOString();if(id||type==='northStar'){snapshot(entity);draft.history=entity.history;if(type==='northStar')state.northStar=draft;else state[type][state[type].findIndex(v=>v.id===id)]=draft;}else state[type].push(draft);save();$('editor').close();render();};
$('close-editor').onclick=$('cancel-editor').onclick=()=>$('editor').close();
$('content').addEventListener('input',e=>{const el=e.target,path=el.dataset.bind;if(!path)return;if(!el.validity.valid){const error=el.closest('.field')?.querySelector('.field-error');if(error)error.textContent='Inserisci un valore valido nel range indicato.';return;}const error=el.closest('.field')?.querySelector('.field-error');if(error)error.textContent='';if(path.startsWith('daily/')){if(!state.daily[dailyDate])state.daily[dailyDate]=emptyDaily();}if(path.startsWith('plans/')){const key=path.split('/')[1];if(!state.plans[key])state.plans[key]=['','',''];}if(el.type==='checkbox'&&['goals','projects','actions'].includes(path.split('/')[0])){const [type,index]=path.split('/');snapshot(state[type][Number(index)]);}
const value=el.type==='checkbox'?el.checked:el.type==='number'&&el.value!==''?Number(el.value):el.value;el.indeterminate=false;setPath(path,value);if(/^actions\/\d+\/done$/.test(path)){const a=state.actions[Number(path.split("/")[1])];if(a.reminder)a.count=a.done?a.target:Math.min(a.count,a.target-1);}save();updateComputed();});
$('content').addEventListener('change',e=>{const el=e.target;if(el.id==='period'&&el.value&&el.validity.valid){const type=el.dataset.period;if(type==='daily')dailyDate=el.value;else if(type==='weekly')weeklyDate=weekStart(el.value,state.settings.weekStart);else if(type==='monthly')monthlyDate=el.value;else financeMonth=el.value;render();}else if(el.id==='entity-filter'){filter=el.value;render();}else if(el.id==='entity-search'){search=el.value;render();}else if(el.dataset.bind==='settings/weekStart'){state.settings.weekStart=Number(el.value);weeklyDate=weekStart(localDate(),state.settings.weekStart);save();}});
function exportAll(){try{const raw=(sandbox?sessionStorage:localStorage).getItem('life-os:v1');if(raw){const legacy=JSON.parse(raw);if(legacy.version===1)state.legacyDays={...state.legacyDays,...legacy.days};}}catch{}const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`life-os-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('content').addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,type,id}=b.dataset;
 if(action==='navigate'){if(b.dataset.area)filter='area:'+b.dataset.area;else if(b.dataset.page!==section)filter='all';if(b.dataset.page!==section){const target=b.dataset.page;section=target;search='';location.hash=target;render();}else render();}
 else if(action==='new')showEditor(type);
 else if(action==='edit')showEditor(type,id);
 else if(action==='edit-north')showEditor('northStar');
 else if(action==='new-project')showEditor('projects',null,{goalId:b.dataset.goal,areaId:state.goals.find(g=>g.id===b.dataset.goal)?.areaId||''});
 else if(action==='journal-action'){const j=state.journals.find(v=>v.id===id);showEditor('actions',null,{name:j.action,sourceJournalId:j.id,notes:'Dalla riflessione: '+j.name});}
 else if(action==='new-action')showEditor('actions',null,{projectId:b.dataset.project||'',scheduledDate:section==='home'?localDate():''});
 else if(action==='today'){dailyDate=localDate();navigate('daily');}
 else if(action==='day'){dailyDate=b.dataset.date;render();}
 else if(action==='period-prev'||action==='period-next'||action==='period-today'){const current=action==='period-today',step=action==='period-prev'?-1:1;if(type==='daily')dailyDate=current?localDate():shiftDate(dailyDate,step);else if(type==='weekly')weeklyDate=current?weekStart(localDate(),state.settings.weekStart):shiftDate(weeklyDate,7*step);else{let value=type==='monthly'?monthlyDate:financeMonth;const d=new Date(value+'-01T12:00:00');d.setMonth(d.getMonth()+step);value=current?localDate().slice(0,7):localDate(d).slice(0,7);if(type==='monthly')monthlyDate=value;else financeMonth=value;}render();}
 else if(action==='use-today'){const source=state[type].find(v=>v.id===id),d=state.daily[localDate()]||emptyDaily();d.bigThing=type==='actions'?source.name:source.nextAction;d.bigDone=false;d.projectId=type==='projects'?source.id:type==='actions'?source.projectId:'';d.actionId=type+':'+id;state.daily[localDate()]=d;save();dailyDate=localDate();navigate('daily');}
 else if(action==='archive'){const entity=state[type].find(v=>v.id===id);snapshot(entity);entity.archived=!entity.archived;save();render();}
 else if(action==='journal-filter'){filter=filter==='archived'?'all':'archived';render();}
 else if(action==='open-history'){if(type==='daily')dailyDate=b.dataset.date;else if(type==='weekly')weeklyDate=b.dataset.date;else if(type==='monthly')monthlyDate=b.dataset.date;if(type==='journal')showEditor('journals',id);else navigate(type);}
 else if(action==='snapshot-review'){const key=type==='weekly'?weeklyDate:monthlyDate,r=state[type][key]||{};snapshot(r);state[type][key]=r;save();render();}
 else if(action==='export')exportAll();
 else if(action==='import')$('backup-file').click();
 else if(action==='export-recovery'){const raw=(sandbox?sessionStorage:localStorage).getItem('life-os:pre-import');if(!raw){showNotice('Non c’è ancora una copia precedente a un’importazione.');return;}const url=URL.createObjectURL(new Blob([raw],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='life-os-prima-import.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 else if(action==='refresh-legacy'){try{const raw=localStorage.getItem('life-os:v1');if(raw){migrateLegacy(state,JSON.parse(raw));save();showNotice('Archivio v1 recuperato: solo le giornate mancanti sono state aggiunte al Daily finale.');}}catch{showNotice('Archivio v1 non leggibile. Nessun dato sovrascritto.');}}
});
$('backup-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Il backup supera 20 MB');const parsed=JSON.parse(await file.text());let incoming;if(parsed.version===1){incoming=createState();incoming.goals=[];incoming.projects=[];incoming.areas=[];incoming=migrateLegacy(incoming,parsed);}else incoming=validateState(parsed);showImport(incoming);}catch(error){showNotice('Importazione non eseguita: '+error.message);}finally{e.target.value='';}};
function showImport(incoming){$('editor-title').textContent='Anteprima importazione';$('editor-kind').textContent='BACKUP LOCALE';$('editor-fields').innerHTML=`<p>${incoming.goals.length} Goals · ${incoming.projects.length} Projects · ${Object.keys(incoming.daily).length} Daily · ${Object.keys(incoming.weekly).length} Weekly · ${Object.keys(incoming.monthly).length} Monthly · ${incoming.journals.length} Journal.</p><p>Unisci gli elementi o ripristina l’intero backup, utile per trasferire l’archivio su un nuovo dispositivo. Una copia locale dell’archivio precedente viene salvata prima dell’importazione.</p><label class="field"><span>Conflitti: stessi identificatori o date</span><select id="import-conflict"><option value="local">Mantieni i dati locali già presenti</option><option value="incoming">Usa i dati del backup per gli elementi coincidenti</option><option value="restore">Ripristina l’intero backup · salva prima una copia dell’archivio locale</option></select></label>${button('Conferma importazione','confirm-import','','primary')}`;$('form-error').textContent='';$('editor-form').querySelector('[type=submit]').hidden=true;$('editor').showModal();const handler=e=>{if(e.target.dataset.action!=='confirm-import')return;try{const mode=$('import-conflict').value,prefer=mode==='incoming';const targetStorage=sandbox?sessionStorage:localStorage;targetStorage.setItem('life-os:pre-import',JSON.stringify(state));const merged=mode==='restore'?structuredClone(incoming):mergeStates(state,incoming,prefer);if(prefer){snapshot(state.northStar);merged.northStar.history=[...(merged.northStar.history||[]),...state.northStar.history];}state=merged;store.replace(state);const saved=save();$('editor').close();render();if(saved)showNotice('Backup importato. La copia dell’archivio precedente è scaricabile da Dati e decisioni.');}catch(error){$('form-error').textContent=error.message;}finally{$('editor-fields').onclick=null;}};$('editor-fields').onclick=handler;}
$('editor').addEventListener('close',()=>{$('editor-fields').onclick=null;$('editor-form').querySelector('[type=submit]').hidden=false;});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'home';if(next!==section){filter='all';search='';}section=next;render(true);});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){store.block();showNotice('Archivio modificato in un’altra scheda. Esporta le modifiche in memoria e ricarica per riprendere.');$('save-status').textContent='Salvataggio sospeso · conflitto tra schede';}});
const googleConnection=createGoogle({onChange:()=>{if(section==='google'||section==='home')render();}});
if(store.warning)showNotice(store.warning);else if(sandbox)showNotice('Sessione di prova separata: nessun dato dell’archivio personale viene modificato.');section=location.hash.slice(1)||'home';render();
if(!state.northStar.vision){fetch('reference.json').then(r=>{if(!r.ok)throw Error('reference');return r.json();}).then(data=>{if(!state.northStar.vision){state.northStar.vision=data.vision;save();if(section==='north')render();}}).catch(()=>showNotice('La visione integrale non è stata caricata. La North Star resta disponibile e modificabile.'));}

function googleConfig(){return state.settings.google||{clientId:'',calendarId:'primary',mailLabel:'INBOX'};}
function googleAgenda(){if(!googleConnection.connected('calendar'))return hint('Collega Google Calendar per vedere qui i prossimi 7 giorni.');return googleConnection.busy.calendar?hint('Caricamento agenda…'):googleConnection.errors.calendar?hint(esc(googleConnection.errors.calendar)):googleConnection.data.calendar.length?googleConnection.data.calendar.map(event=>`<div class="google-item"><strong>${esc(event.summary||'Impegno')}</strong><p>${esc(event.start?.dateTime?new Date(event.start.dateTime).toLocaleString('it-IT',{dateStyle:'medium',timeStyle:'short'}):event.start?.date+' · tutto il giorno')}</p></div>`).join(''):hint('Nessun evento nei prossimi 7 giorni.');}
function googleView(){const c=googleConfig();return heading('Calendar & Gmail','La tua agenda e le email da trasformare in azioni.')+`<div class="home-grid">${card('Configura Google',`<p>Attiva il tuo progetto Google seguendo la <a href="https://developers.google.com/identity/oauth2/web/guides/get-google-api-clientid" target="_blank" rel="noopener">guida passo passo</a>.</p><label class="field"><span>Client ID OAuth · pubblico</span><input id="google-client" value="${esc(c.clientId)}" placeholder="…apps.googleusercontent.com"></label><label class="field"><span>Calendar ID · primary per il calendario personale</span><input id="google-calendar" value="${esc(c.calendarId)}"></label><label class="field"><span>Email da mostrare · primi 15 messaggi</span><select id="google-label"><option value="INBOX" ${c.mailLabel==='INBOX'?'selected':''}>Posta in arrivo</option><option value="STARRED" ${c.mailLabel==='STARRED'?'selected':''}>Speciali</option></select></label><div class="toolbar"><button data-google="config">Salva configurazione</button><button data-google="disconnect">Disconnetti sessioni</button></div><p class="hint">Nessuna password o Client Secret. Token, agenda e lista email restano in memoria e vengono rimossi alla chiusura o disconnessione. Le azioni che confermi restano nel Life OS. Per revocare l’accesso usa <a href="https://myaccount.google.com/connections" target="_blank" rel="noopener">il tuo account Google</a>.</p>`)}${card('Calendar · prossimi 7 giorni',`<div class="toolbar"><button data-google="connect" data-kind="calendar">Collega Calendar</button><button data-google="refresh" data-kind="calendar" ${!googleConnection.connected('calendar')||googleConnection.busy.calendar?'disabled':''}>Aggiorna</button></div>${googleAgenda()}<p role="status">${esc(googleConnection.errors.calendar)} ${googleConnection.updated.calendar?'Aggiornato '+esc(googleConnection.updated.calendar):''}</p>`)}${card('Gmail · messaggi selezionati',`<p>Leggiamo soltanto mittente e oggetto. Apri Gmail per leggere il contenuto. Ogni azione viene prima mostrata per conferma.</p><div class="toolbar"><button data-google="connect" data-kind="gmail">Collega Gmail</button><button data-google="refresh" data-kind="gmail" ${!googleConnection.connected('gmail')||googleConnection.busy.gmail?'disabled':''}>Aggiorna</button></div><p role="status">${esc(googleConnection.errors.gmail)} ${googleConnection.busy.gmail?'Caricamento…':googleConnection.updated.gmail?'Aggiornato '+esc(googleConnection.updated.gmail):''}</p>${googleConnection.data.gmail.map(m=>`<div class="google-item"><strong>${esc(m.subject)}</strong><p>${esc(m.from)}</p><div class="toolbar"><a href="https://mail.google.com/mail/u/0/#search/${encodeURIComponent(m.subject)}" target="_blank" rel="noopener">Apri in Gmail</a><button data-google="action" data-id="${esc(m.id)}">Crea Next Action</button></div></div>`).join('')||hint('Collega Gmail per caricare fino a 15 messaggi. Nessuna email viene inviata o modificata.')}`)}</div>`;}

$('content').addEventListener('click',e=>{const b=e.target.closest('[data-google]');if(!b)return;const c=googleConfig(),kind=b.dataset.kind;switch(b.dataset.google){case 'config':{const clientId=$('google-client').value.trim();if(!validClientId(clientId)){showNotice('Inserisci un Client ID OAuth web valido.');return;}const calendarId=$('google-calendar').value.trim()||'primary',mailLabel=$('google-label').value;googleConnection.disconnect();state.settings.google={clientId,calendarId,mailLabel};save();render();break;}case 'connect':if(!validClientId(c.clientId)){navigate('google');showNotice('Inserisci il Client ID OAuth Google e salva la configurazione.');return;}googleConnection.connect(kind,c.clientId,c.calendarId,c.mailLabel);break;case 'refresh':googleConnection.refresh(kind,c.calendarId,c.mailLabel);break;case 'disconnect':googleConnection.disconnect();break;case 'action':{const m=googleConnection.data.gmail.find(m=>m.id===b.dataset.id);if(!m)return;const existing=state.actions.find(a=>a.sourceEmailId===m.id);if(existing){showEditor('actions',existing.id);return;}showEditor('actions',null,{name:'Gestire: '+m.subject,sourceEmailId:m.id,notes:'Da Gmail: '+m.from+'\nOggetto: '+m.subject});break;}}});

function reminderHome(){const items=state.actions.filter(a=>a.reminder&&!a.archived&&!a.done).sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'));return `<p class="hint">Appunta una commissione o qualcosa che vuoi vivere. Usa quantità e scadenza per “due gite a ottobre”.</p>${button('+ Promemoria','new-reminder','','primary')}${items.slice(0,6).map(a=>`<div class="google-item"><strong>${esc(a.name)}</strong><p>${a.deadline?dateLabel(a.deadline):'Senza scadenza'} · ${a.count||0}/${a.target||1}</p><div class="toolbar">${button('Modifica','edit',`data-type="actions" data-id="${esc(a.id)}"`)}${button('+1 completata','reminder-step',`data-id="${esc(a.id)}"`)}</div></div>`).join('')||hint('Nessun promemoria aperto.')} ${link('Tutte le azioni e le completate','actions')}`;}
function dueBills(){return state.bills.filter(b=>!b.archived&&b.due).sort((a,b)=>a.due.localeCompare(b.due));}
function billHome(){return dueBills().slice(0,4).map(b=>`<div class="google-item"><strong>${esc(b.name)}</strong><p>${dateLabel(b.due)} · ${b.due<localDate()?'Scaduta · da verificare':b.due===localDate()?'Oggi':'In programma'} · ${b.amount===''?'Importo da inserire':'€ '+format(b.amount)}</p>${button('Apri','edit',`data-type="bills" data-id="${esc(b.id)}"`)}</div>`).join('')+link('Gestisci utenze e pagamenti','bills');}
function billView(){const active=state.bills.filter(b=>!b.archived),cost=annualCost(active);return heading('Utenze & ricorrenze','Bollette, contratti, assicurazioni e abbonamenti in un unico posto.',button('+ Utenza / contratto','new','data-type="bills"','primary'))+`<div class="home-kpis">${kpi('CONTRATTI ATTIVI',active.length,'')}${kpi('COSTO MENSILE STIMATO','€ '+format(cost/12),'Solo importi e frequenze compilati')}${kpi('COSTO ANNUALE STIMATO','€ '+format(cost),'Esclude una tantum e variabili')}${kpi('SCADENZE PASSATE',dueBills().filter(b=>b.due<localDate()).length,'Da verificare; non prova di mancato pagamento')}</div><p class="hint">Gli importi previsti servono per pianificare. I pagamenti effettivi sono registrati separatamente e non vengono aggiunti automaticamente alle spese Daily o Monthly. Nessun addebito o promemoria esterno automatico.</p><div class="home-grid">${state.bills.map(b=>card(esc(b.name)+(b.archived?' · archiviata':''),`<p>${esc(b.category)} · ${esc(b.provider)||'Fornitore da inserire'}</p><p>Importo previsto: ${b.amount===''?'—':'€ '+format(b.amount)} · ${b.interval?'ogni '+b.interval+' mesi':'variabile / una tantum'}</p><p>Scadenza: ${b.due?dateLabel(b.due):'—'}<br>Rinnovo: ${b.renewal?dateLabel(b.renewal):'—'}<br>Disdetta entro: ${b.notice?dateLabel(b.notice):'—'}</p><p>${esc(b.method)} ${esc(b.notes)}</p><div class="toolbar">${button('Modifica','edit',`data-type="bills" data-id="${esc(b.id)}"`)}${!b.archived?button('Registra pagamento','bill-payment',`data-id="${esc(b.id)}"`):''}${button(b.archived?'Ripristina':'Archivia','archive',`data-type="bills" data-id="${esc(b.id)}"`)}</div><details><summary>Storico pagamenti (${b.payments.length})</summary>${b.payments.slice().reverse().map((p,i)=>`<p>${dateLabel(p.date)} · € ${format(p.amount)} · scadenza ${esc(p.due)||'—'} ${button('Annulla registrazione','bill-undo',`data-id="${esc(b.id)}" data-payment="${b.payments.length-1-i}"`)}</p>`).join('')||hint('Nessun pagamento registrato.')}</details>`)).join('')||empty('Inserisci la prima bolletta, assicurazione o utenza.')}</div>`;}
$('content').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=state.actions.find(a=>a.id===b.dataset.id),bill=state.bills.find(a=>a.id===b.dataset.id);if(b.dataset.action==='new-reminder')showEditor('actions',null,{reminder:true,target:1,count:0});else if(b.dataset.action==='reminder-step'&&a){snapshot(a);a.count=Math.min(a.target,(a.count||0)+1);a.done=a.count===a.target;save();render();}else if(b.dataset.action==='bill-payment'&&bill){$('editor-kind').textContent='PAGAMENTO';$('editor-title').textContent=bill.name;$('editor-fields').innerHTML=`${input(field('paymentDate','Data pagamento','date',{required:true}),localDate())}${input(field('paymentAmount','Importo effettivo · €','number',{min:0,required:true}),bill.amount)}${input(field('paymentNext','Prossima scadenza · verifica prima di confermare','date'),nextDue(bill.due,bill.interval))}${button('Conferma pagamento','confirm-bill','','primary')}<p class="hint">Registra un pagamento già effettuato. Puoi correggere la prossima data; non viene eseguito alcun addebito.</p>`;$('form-error').textContent='';$('editor-form').querySelector('[type=submit]').hidden=true;$('editor').showModal();$('editor-fields').onclick=event=>{if(event.target.dataset.action!=='confirm-bill')return;if(!$('editor-form').reportValidity())return;snapshot(bill);bill.payments.push({date:$('field-paymentDate').value,amount:Number($('field-paymentAmount').value),due:bill.due,nextDue:$('field-paymentNext').value});bill.due=$('field-paymentNext').value;save();$('editor').close();render();};}else if(b.dataset.action==='bill-undo'&&bill){const index=Number(b.dataset.payment),p=bill.payments[index];if(!p)return;snapshot(bill);if(index===bill.payments.length-1&&bill.due===p.nextDue)bill.due=p.due;bill.payments.splice(index,1);save();render();}});

function operationalHome(){const today=localDate(),d=startDay(today),items=operationalItems(state,today),agenda=googleConnection.data.calendar,c=googleConfig(),connected=googleConnection.connected('calendar');const tasks=items.todayActions;return `<div class="ops-home"><section class="ops-focus"><span class="eyebrow">LA COSA CHE CONTA OGGI</span><h2>${esc(d.bigThing)||'Scegli la tua One Big Thing'}</h2>${button('Apri check-in','today','','primary')}</section><div class="ops-grid">${card('Agenda · Google Calendar',`<div class="toolbar"><button data-google="connect" data-kind="calendar">${connected?'Cambia / rinnova accesso':'Collega Calendar'}</button><button data-google="refresh" data-kind="calendar" ${!connected||googleConnection.busy.calendar?'disabled':''}>Aggiorna agenda</button>${link('Configura','google')}</div><p class="hint" role="status">${googleConnection.busy.calendar?'Aggiornamento…':connected?'Collegato · aggiornamento ogni 5 minuti mentre la Home è aperta':'Accesso richiesto · Calendar in sola lettura'}${googleConnection.updated.calendar?' · ultimo aggiornamento '+esc(googleConnection.updated.calendar):''}</p>${googleConnection.errors.calendar?`<p class="notice">${esc(googleConnection.errors.calendar)}</p>`:''}${connected?['Oggi','Prossimi 6 giorni'].map((label,i)=>{const events=agenda.filter(e=>i?eventDay(e)>today:eventDay(e)===today);return `<h3>${label}</h3>${events.map(e=>{const url=safeGoogleLink(e.htmlLink);return `<div class="agenda-event"><time>${e.start?.date?dateLabel(e.start.date)+' · tutto il giorno':new Date(e.start.dateTime).toLocaleString('it-IT',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</time><strong>${esc(e.summary||'Impegno')}</strong>${e.location?`<small>${esc(e.location)}</small>`:''}${url?`<a href="${esc(url)}" target="_blank" rel="noopener">Apri evento ↗</a>`:''}</div>`;}).join('')||hint(googleConnection.busy.calendar?'Caricamento…':'Nessun evento in questo periodo.')}`;}).join(''):hint(c.clientId?'Premi Collega Calendar per autorizzare il tuo account Google.':'Inserisci il tuo Client ID in Configura, poi collega Calendar.')}<p class="hint">L’agenda si aggiorna durante la sessione. Dopo ricaricamento o scadenza serve ricollegare Google; gli eventi non vengono salvati nei backup.</p>`)}${card('Azioni di oggi',button('+ Aggiungi','new-action','','primary')+tasks.map(a=>`<div class="google-item"><label class="check"><input type="checkbox" data-op-complete="${esc(a.id)}"><span>${esc(a.name)}</span></label><div class="toolbar">${button('One Big Thing','use-today',`data-type="actions" data-id="${esc(a.id)}"`)}${button('Modifica','edit',`data-type="actions" data-id="${esc(a.id)}"`)}<button data-op-unplan="${esc(a.id)}">Togli da oggi</button></div></div>`).join('')+(tasks.length?'':hint('Scegli le azioni dalla lista qui sotto.'))+`<details><summary>Scegli dalle Next Actions</summary>${state.actions.filter(a=>!a.archived&&!a.done&&a.scheduledDate!==today).map(a=>`<div class="google-item"><strong>${esc(a.name)}</strong><button data-op-plan="${esc(a.id)}">Pianifica oggi</button></div>`).join('')||hint('Crea una nuova azione per iniziare.')}${state.projects.filter(p=>!p.archived&&p.status==='Active'&&p.nextAction&&!p.nextDone).map(p=>`<div class="google-item"><strong>${esc(p.nextAction)}</strong>${button('One Big Thing','use-today',`data-type="projects" data-id="${esc(p.id)}"`)}</div>`).join('')}</details>`)}${card('Scadenze · entro 7 giorni',items.due.map(v=>`<div class="ops-due"><div><strong>${esc(v.name)}</strong><small>${esc(v.kind)} · ${dateLabel(v.date)}${v.date<today?' · da verificare':''}</small></div>${button('Apri','edit',`data-type="${v.type}" data-id="${esc(v.id)}"`)}</div>`).join('')||hint('Nessuna scadenza registrata nei prossimi 7 giorni.'))}${card('Projects da sbloccare',items.stalled.map(p=>compactEntity(p,'projects')).join('')||hint('I progetti attivi hanno una prossima azione.')+link('Tutti i Projects','projects'))}</div></div>`;}
$('content').addEventListener('click',e=>{const b=e.target.closest('[data-op-plan],[data-op-unplan],[data-op-complete]');if(!b)return;const id=b.dataset.opPlan||b.dataset.opUnplan||b.dataset.opComplete,a=state.actions.find(a=>a.id===id);if(!a)return;snapshot(a);if(b.dataset.opComplete){a.done=true;if(a.reminder)a.count=a.target;}else a.scheduledDate=b.dataset.opPlan?localDate():'';save();render();});
function refreshHomeCalendar(){if(section!=='home'||document.hidden||!googleConnection.connected('calendar')||googleConnection.busy.calendar)return;const c=googleConfig();googleConnection.refresh('calendar',c.calendarId,c.mailLabel);}
setInterval(refreshHomeCalendar,5*60*1000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshHomeCalendar();});
window.addEventListener('hashchange',()=>{if(section==='home')refreshHomeCalendar();});
